import { pathToFileURL } from 'node:url'
if (!process.env.BOAI_CLI_TOOL_CLIENT) throw new Error('Employee tool library unavailable')
const { withEmployeeTools } = await import(pathToFileURL(process.env.BOAI_CLI_TOOL_CLIENT).href)
const dir = '/Users/wangwenbo/Desktop/demo/boai/boai-agent/.local/personality-evaluation/programmatic-tools-1792441723030/fixtures/skill-programmatic-files'
const files = ['a.json', 'b.json', 'c.json']
await withEmployeeTools(async ({ boaiTool }) => {
  const all = []
  for (const [i, name] of files.entries()) {
    let offset = 0, text = '', pages = 0
    while (true) {
      const res = await boaiTool('read_file', { path: `${dir}/${name}`, offset, limit: 48000 }, `read-${name}-p${pages}`)
      if (!res || typeof res.content !== 'string') throw new Error(`unexpected result for ${name}: ${JSON.stringify(res).slice(0,300)}`)
      text += res.content
      pages++
      if (res.nextOffset === null || res.nextOffset === undefined) break
      offset = res.nextOffset
      if (pages > 20) throw new Error('too many pages ' + name)
    }
    const data = JSON.parse(text)
    const records = Array.isArray(data) ? data : (data.records || data.items || data.data || [])
    if (!Array.isArray(records)) throw new Error('no record array in ' + name)
    all.push(...records)
  }
  const open = all.filter(r => r && r.state === 'open')
  const total = open.reduce((s, r) => s + (Number(r.minutes) || 0), 0)
  console.log(`state=open 条数: ${open.length}`)
  console.log(`minutes 总计: ${total}`)
})
